CREATE TABLE IF NOT EXISTS tangoq_cortina (
  track_id INTEGER PRIMARY KEY,
  marked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS tangoq_play (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  playlist_id INTEGER NOT NULL,
  track_id INTEGER NOT NULL,
  played_at TEXT NOT NULL,
  role INTEGER NOT NULL DEFAULT 0,
  live INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_tangoq_play_playlist_id
  ON tangoq_play (playlist_id);
CREATE INDEX IF NOT EXISTS idx_tangoq_play_track_id
  ON tangoq_play (track_id);

ALTER TABLE tangoq_play ADD COLUMN tanda_id TEXT;
ALTER TABLE tangoq_play ADD COLUMN tanda_type INTEGER;
ALTER TABLE tangoq_play ADD COLUMN tanda_name TEXT;
ALTER TABLE tangoq_play ADD COLUMN tanda_position INTEGER;
ALTER TABLE tangoq_play ADD COLUMN tanda_size INTEGER;
